-- Insert a row into shared_export with manually constructed JSON
-- Latest per-session measurements for Partner University
INSERT INTO shared_export (recipient_org, payload, created_at) 
VALUES ('Partner University - Sleep & Cognition Lab', json(
    '{"export_created_at": "2027-01-01T12:00:00Z", "export_description": "Latest per-session measurements for partner university analysts - re-run checks", "record_count": 33, "data": ' || json_group_array(
        json(
            '{"session_id": "' || m.session_id || '", "participant_id": "' || m.participant_id || '", "condition": "' || m.condition || '", "cognitive_score": ' || m.cognitive_score || ', "reaction_ms": ' || m.reaction_ms || ', "recorded_at": "' || m.recorded_at || '", "status": "' || m.status || '"}'
        )
    )
    FROM measurements m
    GROUP BY session_id
    HAVING COUNT(*) = 1
) || '}"'
), datetime('now'));

WITH latest AS (
    SELECT 
        m.*
    FROM (
        SELECT session_id, recorded_at, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY recorded_at DESC) as rn
        FROM measurements
    ) t
    WHERE t.rn = 1
)
SELECT session_id, participant_id, condition, cognitive_score, reaction_ms, recorded_at, status, notes FROM latest;

WITH latest AS (
    SELECT mm.*
    FROM (
        SELECT session_id, recorded_at, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY recorded_at DESC) as rn
        FROM measurements
    ) mm
    WHERE mm.rn = 1
)
SELECT session_id, participant_id, condition, cognitive_score, reaction_ms, recorded_at, status, notes FROM latest;

WITH latest AS (
    SELECT t.session_id, t.participant_id, t.condition, t.cognitive_score, t.reaction_ms, t.recorded_at, t.status, t.notes
    FROM (
        SELECT * FROM (
            SELECT session_id, recorded_at, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY recorded_at DESC) as rn
            FROM measurements
        ) t
        WHERE rn = 1
    ) t
)
SELECT * FROM latest;

